#include "stdafx.h"#include "HcdConnection.h"void SHcdConnection::Transfer(){  if( !sourcePin.panaVal || !sinkPin.panaVal )    return;  switch( sourcePin.type )  {  case ehtAnalog32:    switch( sinkPin.type )    {    case ehtAnalog32:      *sinkPin.panaVal = *sourcePin.panaVal;      break;    case ehtBool:    case ehtEnum:      *sinkPin.pbVal = (tBool)*sourcePin.panaVal;      break;    case ehtDigital32:      *sinkPin.pdigVal = *sourcePin.panaVal;      break;    default:      ASSD(0);      break;    }    break;  case ehtDigital32:    switch( sinkPin.type )    {    case ehtAnalog32:      *sinkPin.panaVal = *sourcePin.pdigVal;      break;    case ehtDigital32:      *sinkPin.pdigVal = *sourcePin.pdigVal;      break;    case ehtBool:    case ehtEnum:      *sinkPin.pbVal = *sourcePin.pdigVal;      break;    default:      ASSD(0);      break;    }    break;  case ehtBool:  case ehtEnum:    switch( sinkPin.type )    {    case ehtAnalog32:      *sinkPin.panaVal = *sourcePin.pbVal;      break;    case ehtDigital32:      *sinkPin.pdigVal = *sourcePin.pbVal;      break;    case ehtBool:    case ehtEnum:      *sinkPin.pbVal = *sourcePin.pbVal;      break;    default:      ASSD(0);      break;    }    break;  default:    ASSD(0);    break;  }}